    15	\section{Genus}
    16	
    17	\begin{definition}[Genus]
    18	  \label{def:genus}
    19	  \lean{AlgebraicGeometry.genus}
    20	  \leanok
    21	  \uses{def:moduleKSheaf, def:HModule}
    22	  \provenancetag{ADAPTED}
    23	  The \emph{genus} of a smooth proper curve \(C\) over \(k\) is
    24	  \[
    25	    g(C) \;=\; \dim_k H^1\!\bigl(C, \struct C\bigr),
    26	  \]
    27	  the \(k\)-dimension of the first cohomology group of the structure sheaf, viewed as a sheaf
    28	  of \(k\)-modules on the small Zariski site of \(C\) (Definition~\ref{def:moduleKSheaf}),
    29	  with cohomology the \(\Ext\)-groups from the constant sheaf
    30	  (Definition~\ref{def:HModule}).
    31	\end{definition}
    32	
    33	\section{The Jacobian as an abelian variety}
    34	
    35	\begin{definition}[Jacobian]
    36	 \label{def:jacobian}
    37	 \lean{AlgebraicGeometry.Jacobian}
    38	 \uses{def:pic0Functor}
    39	 \source{kleiman-picard}
    40	 \provenancetag{ADAPTED}
    41	  The \emph{Jacobian} \(\Jac(C)\) of a smooth proper curve \(C\) over \(k\) is the identity
    42	  component \(\Pic^0_{C/k}\) of the relative Picard scheme of \(C\) over \(k\): the \(k\)-scheme
    43	  representing the degree-zero subfunctor of the \'etale-sheafified relative Picard functor.
    44	\end{definition}
    45	
    46	\begin{proposition}[Group scheme structure]
    47	  \label{prop:jacobian_grpobj}
    48	  \uses{def:jacobian}
    49	  \lean{AlgebraicGeometry.Jacobian.instGrpObj}
    50	  \provenancetag{ADAPTED}
    51	  \(\Jac(C)\) is a commutative group scheme over \(k\), with multiplication induced by the tensor
    52	  product of line bundles.
    53	\end{proposition}
    54	
    55	\begin{theorem}[Smoothness of the Jacobian]
    56	  \label{thm:jacobian_smooth}
    57	  \uses{def:genus, def:jacobian}
    58	  \lean{AlgebraicGeometry.Jacobian.smoothOfRelativeDimension_genus}
    59	  \provenancetag{ADAPTED}
    60	  \(\Jac(C)\) is smooth over \(k\) of relative dimension \(g(C)\).
    61	\end{theorem}
    62	
    63	\begin{theorem}[Properness of the Jacobian]
    64	  \label{thm:jacobian_proper}
    65	  \uses{def:jacobian}
    66	  \lean{AlgebraicGeometry.Jacobian.instIsProper}
    67	  \provenancetag{ADAPTED}
    68	  \alignmentcheck{TO CHECK: the named Lean target is unresolved; \texttt{Challenge.lean}
    69	  declares this instance anonymously.}
    70	  \(\Jac(C)\) is proper over \(k\).
    71	\end{theorem}
    72	
    73	\begin{theorem}[Geometric irreducibility of the Jacobian]
    74	  \label{thm:jacobian_geomirred}
    75	  \uses{def:jacobian}
    76	  \lean{AlgebraicGeometry.Jacobian.instGeometricallyIrreducible}
    77	  \provenancetag{ADAPTED}
    78	  \alignmentcheck{TO CHECK: the named Lean target is unresolved; \texttt{Challenge.lean}
    79	  declares this instance anonymously.}
    80	  \(\Jac(C)\) is geometrically irreducible over \(k\).
    81	\end{theorem}
    82	
    83	In particular \(\Jac(C)\) is an abelian variety over \(k\) of dimension \(g(C)\).
