    85	\section{The Abel--Jacobi map and the universal property}
    86	
    87	\begin{definition}[Abel--Jacobi map]
    88	  \label{def:ofCurve}
    89	  \uses{def:jacobian}
    90	  \lean{AlgebraicGeometry.Jacobian.ofCurve}
    91	  \provenancetag{ADAPTED}
    92	  For a \(k\)-rational point \(P : \Spec k \to C\), the \emph{Abel--Jacobi map}
    93	  \(\varphi_P : C \to \Jac(C)\) sends a point \(Q\) to the class of the line bundle
    94	  \(\struct C(Q - P)\).
    95	\end{definition}
    96	
    97	\begin{lemma}[Base point maps to the origin]
    98	  \label{lem:comp_ofCurve}
    99	  \uses{def:ofCurve, prop:jacobian_grpobj}
   100	  \lean{AlgebraicGeometry.Jacobian.comp_ofCurve}
   101	  \provenancetag{ADAPTED}
   102	  The Abel--Jacobi map \(\varphi_P\) sends the base point \(P\) to the neutral element of
   103	  \(\Jac(C)\): \(\varphi_P \circ P = 0\).
   104	\end{lemma}
   105	
   106	\begin{theorem}[Universal property of the Jacobian]
   107	  \label{thm:exists_unique_ofCurve_comp}
   108	  \uses{def:ofCurve, lem:comp_ofCurve, prop:jacobian_grpobj}
   109	  \lean{AlgebraicGeometry.Jacobian.exists_unique_ofCurve_comp}
   110	  \source{abelian-varieties:page-0110}
   111	  \provenancetag{ADAPTED}
   112	  \alignmentcheck{TO CHECK: Milne's Proposition~6.1 assumes \(g(C)>0\), whereas this node and its
   113	  Lean declaration also quantify over genus zero (source page~0110).}
   114	  \(\Jac(C)\) is the Albanese variety of \(C\): for every abelian variety \(A\) over \(k\) and every
